  /**
   * RPC Method: Send job_complete message
   *
   * @param {string} pipeline - Pipeline type
   * @param {Object} payload - Completion payload (pipeline-specific)
   * @returns {Promise<{success: boolean}>}
   */
  async complete(pipeline, payload) {
    if (!this.webSocket) {
      console.warn(`[${this.jobId}] No WebSocket connection available`);
      return { success: false };
    }

    // Calculate expiry timestamp (24 hours from now)
    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

    const message = {
      type: "job_complete",
      jobId: this.jobId,
      pipeline,
      timestamp: Date.now(),
      version: "1.0.0",
      payload: {
        type: "job_complete",
        pipeline,
        ...payload,
        expiresAt, // Add expiry timestamp to payload
      },
    };

    try {
      const messageStr = JSON.stringify(message);
      this.validateMessageSize(messageStr); // ISSUE #135: Validate size
      this.webSocket.send(messageStr);
      console.log(`[${this.jobId}] Job complete message sent`);

      // Close connection after completion
      setTimeout(() => {
        if (this.webSocket) {
          this.webSocket.close(
            WebSocketCloseCodes.NORMAL_CLOSURE,
            "Job completed",
          );
          this.cleanup();
        }
      }, 1000); // 1 second delay to ensure message is delivered

      return { success: true };
    } catch (error) {
      console.error(`[${this.jobId}] Failed to send job_complete:`, error);
      return { success: false };
    }
  }

  /**
   * RPC Method: Send error message (v2 schema)
   *
   * @param {string} pipeline - Pipeline type
   * @param {Object} payload - Error payload (code, message, details, retryable)
   * @returns {Promise<{success: boolean}>}
   */
  async sendError(pipeline, payload) {
    if (!this.webSocket) {
      console.warn(`[${this.jobId}] No WebSocket connection available`);
      return { success: false };
    }

    // BREAKING CHANGE (Issue #167): Align WebSocket errors with HTTP canonical format
    // WebSocket errors now use ResponseEnvelope structure for consistency
    const message = {
      type: "error",
      jobId: this.jobId,
      pipeline,
      timestamp: Date.now(),
      version: "2.0.0", // Bumped to 2.0.0 for breaking change
      payload: {
        type: "error",
        data: null, // Always null for errors (matches HTTP ResponseEnvelope)
        metadata: {
          timestamp: new Date().toISOString(), // ISO 8601 format (matches HTTP)
        },
        error: {
          message: payload.message,
          code: payload.code,
          details: payload.details,
        },
        retryable: payload.retryable, // WebSocket-specific extension
      },
    };

    try {
      const messageStr = JSON.stringify(message);
      this.validateMessageSize(messageStr); // ISSUE #135: Validate size
      this.webSocket.send(messageStr);
      console.log(
        `[${this.jobId}] Error message sent (v2 schema): ${payload.code}`,
      );

      // Close connection after error with appropriate code
      setTimeout(() => {
        if (this.webSocket) {
          this.webSocket.close(
            WebSocketCloseCodes.INTERNAL_ERROR,
            "Job failed",
          );
          this.cleanup();
        }
      }, 1000); // 1 second delay to ensure message is delivered

      return { success: true };
    } catch (error) {
      console.error(`[${this.jobId}] Failed to send error:`, error);
      return { success: false };
    }
  }

  /**
   * ISSUE #135: Validate WebSocket message size
   * Cloudflare WebSocket limit: 32 MiB per message
   *
   * @param {string} message - Serialized JSON message
   * @throws {Error} If message exceeds 32 MiB limit
   */
  validateMessageSize(message) {
    const sizeBytes = new Blob([message]).size;
    const sizeMB = sizeBytes / (1024 * 1024);

    // Cloudflare Workers WebSocket limit: 32 MiB
    const MAX_SIZE_MB = 32;

    if (sizeMB > MAX_SIZE_MB) {
      const error = `WebSocket message too large: ${sizeMB.toFixed(2)} MB (max ${MAX_SIZE_MB} MB)`;
      console.error(`[${this.jobId}] ${error}`);
      throw new Error(error);
    }

    // Warn for large messages (>10 MB) that are approaching the limit
    if (sizeMB > 10) {
      console.warn(
        `[${this.jobId}] ⚠️ Large WebSocket message: ${sizeMB.toFixed(2)} MB (consider using summary-only pattern)`,
      );
    }

    return sizeMB;
  }

  /**
   * Internal cleanup - Full cleanup including storage
   */
  async cleanup() {
    // Clear in-memory state
    this.webSocket = null;
    this.jobId = null;
    this.isReady = false;
    this.readyPromise = null;
    this.readyResolver = null;

    // CRITICAL: Delete auth tokens from storage to prevent memory leak (Issue #101)
    // Tokens accumulate indefinitely if not cleaned up, causing storage bloat
    await this.storage.delete("authToken");
    await this.storage.delete("authTokenExpiration");

    // IMPORTANT: Do NOT clear "canceled" status from storage
    // Worker needs to check cancellation state after socket closes

    console.log("[ProgressDO] Cleanup complete");
  }

